/**
 * frontend/src/auth_service.js - VERSION EXPERT ALIGNÉE
 * ✅ EXPORT API INSTANCE (Utilisée par api_service.js)
 * Gère le cycle de vie JWT (Login, Register, Refresh, Expiry)
 */

import axios from 'axios';

const API_BASE_URL = 'http://localhost:8000/api';
const ACCESS_TOKEN_KEY = 'token'; // Harmonisé avec tes autres scripts
const REFRESH_TOKEN_KEY = 'refresh_token';
const USER_KEY = 'user';

/**
 * ======================
 * INSTANCE AXIOS EXPORTÉE
 * ======================
 */
export const api = axios.create({
  baseURL: API_BASE_URL,
  timeout: 20000,
  headers: {
    'Content-Type': 'application/json',
  },
});

/**
 * HELPER ERREURS UNIFORME
 */
const getErrorMessage = (error, fallback) => {
  return (
    error?.response?.data?.error ||
    error?.response?.data?.message ||
    error?.message ||
    fallback
  );
};

/**
 * ======================
 * INTERCEPTORS
 * ======================
 */

// Requête : Injecter le token
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem(ACCESS_TOKEN_KEY);
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    console.log(`📤 [${config.method?.toUpperCase()}] ${config.url}`);
    return config;
  },
  (error) => Promise.reject(error)
);

// Réponse : Gestion globale des erreurs
api.interceptors.response.use(
  (response) => {
    console.log(`✅ [${response.status}] ${response.config.url}`);
    return response;
  },
  (error) => {
    // Si 401 (Unauthorized), on nettoie tout
    if (error.response?.status === 401) {
      console.warn('❌ Session expirée ou non autorisée');
      localStorage.removeItem(ACCESS_TOKEN_KEY);
      localStorage.removeItem(REFRESH_TOKEN_KEY);
      localStorage.removeItem(USER_KEY);
      // window.location.href = '/'; // Activer si tu veux rediriger au login
    }
    return Promise.reject(error);
  }
);

/**
 * ======================
 * AUTH SERVICE CLASS
 * ======================
 */
class AuthService {
  /**
   * LOGIN
   */
  async login(username, password) {
    try {
      console.log('🔐 [AUTH] Login attempt:', { username });
      const response = await api.post('/auth/login/', { username, password });

      const { access, refresh, user } = response.data;

      localStorage.setItem(ACCESS_TOKEN_KEY, access);
      localStorage.setItem(REFRESH_TOKEN_KEY, refresh);
      localStorage.setItem(USER_KEY, JSON.stringify(user));

      console.log('✅ [AUTH] Login successful!');
      return { success: true, user };
    } catch (error) {
      const errorMsg = getErrorMessage(error, 'Login failed');
      console.error('❌ [AUTH] Login failed:', errorMsg);
      return { success: false, error: errorMsg };
    }
  }

  /**
   * REGISTER
   */
  async register(username, email, password, passwordConfirm, firstName = '') {
    try {
      if (password !== passwordConfirm) {
        return { success: false, error: 'Les mots de passe ne correspondent pas' };
      }

      const response = await api.post('/auth/register/', {
        username,
        email,
        password,
        password_confirm: passwordConfirm,
        first_name: firstName
      });

      const { access, refresh, user } = response.data;
      localStorage.setItem(ACCESS_TOKEN_KEY, access);
      localStorage.setItem(REFRESH_TOKEN_KEY, refresh);
      localStorage.setItem(USER_KEY, JSON.stringify(user));

      return { success: true, user };
    } catch (error) {
      return { success: false, error: getErrorMessage(error, 'Registration failed') };
    }
  }

  /**
   * LOGOUT
   */
  async logout() {
    try {
      const refreshToken = localStorage.getItem(REFRESH_TOKEN_KEY);
      if (refreshToken) {
        await api.post('/auth/logout/', { refresh: refreshToken });
      }
    } catch (err) {
      console.warn('⚠️ [AUTH] Logout notification failed');
    } finally {
      this.clearAuth();
    }
  }

  /**
   * REFRESH TOKEN
   */
  async refreshToken() {
    try {
      const refresh = localStorage.getItem(REFRESH_TOKEN_KEY);
      if (!refresh) throw new Error('No refresh token');

      const response = await api.post('/auth/refresh/', { refresh });
      const { access } = response.data;

      localStorage.setItem(ACCESS_TOKEN_KEY, access);
      return { success: true, access };
    } catch (error) {
      this.clearAuth();
      return { success: false };
    }
  }

  /**
   * UTILS & HELPERS
   */
  clearAuth() {
    localStorage.removeItem(ACCESS_TOKEN_KEY);
    localStorage.removeItem(REFRESH_TOKEN_KEY);
    localStorage.removeItem(USER_KEY);
  }

  isAuthenticated() {
    return !!localStorage.getItem(ACCESS_TOKEN_KEY);
  }

  getUser() {
    const user = localStorage.getItem(USER_KEY);
    return user ? JSON.parse(user) : null;
  }

  // Vérifie si le token JWT est expiré (en décodant le payload)
  isTokenExpired() {
    try {
      const token = localStorage.getItem(ACCESS_TOKEN_KEY);
      if (!token) return true;

      const payload = JSON.parse(atob(token.split('.')[1]));
      return Date.now() >= payload.exp * 1000;
    } catch {
      return true;
    }
  }

  /**
   * SECURITÉ : Vérifie et rafraîchit le token si nécessaire avant une action
   */
  async ensureAuthenticated() {
    if (!this.isAuthenticated()) return { authenticated: false };

    if (this.isTokenExpired()) {
      const result = await this.refreshToken();
      if (!result.success) return { authenticated: false };
    }

    return { authenticated: true, user: this.getUser() };
  }
}

export default new AuthService();
